MatrixBaseApis.prototype.identityHashedLookup = async function (addressPairs, identityAccessToken) {
  const params = {};

  const hashes = await this.getIdentityHashDetails(identityAccessToken);

  if (!hashes || !hashes['lookup_pepper'] || !hashes['algorithms']) {
    throw new Error("Unsupported identity server: bad response");
  }

  params['pepper'] = hashes['lookup_pepper'];
  const localMapping = {};

  if (hashes['algorithms'].includes('sha256')) {
    const olmutil = new global.Olm.Utility();
    params["addresses"] = addressPairs.map(p => {
      const addr = p[0].toLowerCase();
      const med = p[1].toLowerCase();
      const hashed = olmutil.sha256(`${addr} ${med} ${params['pepper']}`).replace(/\+/g, '-').replace(/\//g, '_');
      localMapping[hashed] = p[0];
      return hashed;
    });
    params["algorithm"] = "sha256";
  } else if (hashes['algorithms'].includes('none')) {
    params["addresses"] = addressPairs.map(p => {
      const addr = p[0].toLowerCase();
      const med = p[1].toLowerCase();
      const unhashed = `${addr} ${med}`;
      localMapping[unhashed] = p[0];
      return unhashed;
    });
    params["algorithm"] = "none";
  } else {
    throw new Error("Unsupported identity server: unknown hash algorithm");
  }

  const response = await this._http.idServerRequest(undefined, "POST", "/lookup", params, _httpApi.PREFIX_IDENTITY_V2, identityAccessToken);
  if (!response || !response['mappings']) return [];

  const foundAddresses = [];

  for (const hashed of Object.keys(response['mappings'])) {
    const mxid = response['mappings'][hashed];
    const plainAddress = localMapping[hashed];

    if (!plainAddress) {
      throw new Error("Identity server returned more results than expected");
    }

    foundAddresses.push({
      address: plainAddress,
      mxid
    });
  }

  return foundAddresses;
};

